    faqs: {
      ko: [
        { q: "앱 아이디어만 있어도 진행할 수 있나요?", a: "가능합니다. 핵심 문제와 기능을 정리한 뒤 Information Architecture와 User Flow부터 설계할 수 있습니다." },
        { q: "아직 개발하지 않은 앱도 가능한가요?", a: "가능합니다. 신규 제품은 Wireframe과 UI/UX 설계 후 개발 단계로 연결할 수 있습니다." },
        { q: "기존 앱을 리디자인할 수도 있나요?", a: "가능합니다. 기존 구조와 주요 Flow를 검토한 뒤 개선이 필요한 영역을 중심으로 재설계할 수 있습니다." },
        { q: "화면 몇 개까지 디자인해주나요?", a: "화면 수는 프로젝트 범위와 기능 복잡도에 따라 결정하며 견적 단계에서 정확히 정의합니다. 무제한으로 포함되지 않습니다." },
        { q: "iOS와 Android 둘 다 가능한가요?", a: "가능합니다. 필요한 플랫폼 범위와 플랫폼별 차이를 프로젝트 시작 전에 정합니다. 특정 가이드라인 100% 준수를 보장하지는 않습니다." },
        { q: "프로토타입도 받을 수 있나요?", a: "프로젝트 범위에 따라 핵심 User Flow를 확인할 수 있는 Prototype을 제공할 수 있습니다." },
        { q: "디자인 시스템도 포함되나요?", a: "기본 UI Component System은 프로젝트 범위에 포함될 수 있습니다. 전체 규모의 Design System은 별도 범위가 될 수 있습니다." },
        { q: "개발도 같이 해주나요?", a: "프로젝트에 따라 Design + Development 형태로 진행할 수 있습니다. 개발 포함 여부와 기술 범위는 별도로 협의합니다." },
        { q: "앱스토어 출시까지 가능한가요?", a: "개발과 출시 지원이 포함된 프로젝트에서는 스토어 제출을 위한 준비를 지원할 수 있습니다. 다만 Apple 또는 Google의 최종 심사 승인을 보장하지 않습니다." },
        { q: "UX Research도 하나요?", a: "프로젝트에 따라 경쟁 서비스 분석, 인터뷰, 사용성 테스트 등을 추가 범위로 진행할 수 있습니다." },
        { q: "수정은 몇 번 가능한가요?", a: "수정 라운드는 프로젝트 범위와 견적 단계에서 사전에 확정합니다." },
        { q: "AI 앱도 가능한가요?", a: "가능합니다. AI 기능 자체뿐 아니라 입력, 생성 대기, 결과, 재생성, 오류와 사용 제한 등 AI 제품에서 필요한 사용자 경험도 프로젝트 범위에 따라 설계할 수 있습니다." },
        { q: "프로젝트 기간과 시작가는?", a: "기본 범위 기준 약 3–6주, 시작가 ₩800,000부터입니다. 화면 수와 복잡도, 개발 포함 여부에 따라 달라질 수 있습니다." },
        { q: "Web Design과 뭐가 다른가요?", a: "Web Design은 정보 탐색·콘텐츠·전환 중심의 웹 경험에 가깝고, App UI/UX는 반복 사용·기능 실행·상태·인터랙션 중심의 제품 경험에 가깝습니다." },
      ],
      en: [
        { q: "Can we start with only an app idea?", a: "Yes. After clarifying the core problem and features, we can start from information architecture and user flows." },
        { q: "Can you design an app that is not built yet?", a: "Yes. New products can move from wireframes and UI/UX into a later development phase." },
        { q: "Can you redesign an existing app?", a: "Yes. We review current structure and key flows, then redesign where improvement is needed." },
        { q: "How many screens are included?", a: "Screen count is set by scope and complexity and defined precisely at quoting — not unlimited." },
        { q: "Can you cover both iOS and Android?", a: "Yes. Platform scope and platform differences are set before kickoff. We do not claim 100% guideline compliance." },
        { q: "Do we get a prototype?", a: "Depending on scope, we can provide a prototype for core user flows." },
        { q: "Is a design system included?", a: "A basic UI component system may be in scope. A full-scale design system can be a separate scope." },
        { q: "Do you also develop the app?", a: "Design + Development is possible by project. Inclusion and technical scope are agreed separately." },
        { q: "Can you support store launch?", a: "When development and launch support are in scope, we can help prepare store submission. Apple or Google approval is not guaranteed." },
        { q: "Do you do UX research?", a: "Competitive review, interviews, and usability testing can be added by scope." },
        { q: "How many revision rounds?", a: "Revision rounds are set in scope and quoting before work starts." },
        { q: "Can you design AI apps?", a: "Yes. Beyond the AI feature itself, we can design input, generating wait, results, regenerate, errors, and usage limits by scope." },
        { q: "What are timeline and starting price?", a: "About 3–6 weeks for basic scope, from ₩800,000. Screen count, complexity, and whether development is included can change the quote." },
        { q: "How is this different from Web Design?", a: "Web Design centers on exploration, content, and conversion. App UI/UX centers on repeat use, feature execution, states, and interaction." },
      ],
    },
