      en: "Types do not share one fixed scope or price — quotes follow project scale.\n\nAd-dedicated pages can connect AD MESSAGE → LANDING HERO → VALUE → PROOF → CTA. Ad ops and performance optimization are not in the basic service.\n\nEarly products can use IDEA → VALUE → LANDING → WAITLIST/INQUIRY → RESPONSE → DECISION. A Landing Page alone does not guarantee market fit, investment, or business success.",
