      ko: "모든 정보를 같은 크기로 보여주지 않습니다. 빠르게 스캔하는 사용자도 Primary와 Secondary만으로 핵심을 이해할 수 있어야 합니다.\n\nVisual Content 프로젝트는 Brand Identity 전체를 새로 만드는 작업과 다릅니다. 기존 Identity가 있다면 콘텐츠에 일관되게 적용하고, 없다면 필요한 최소한의 Visual Direction을 별도로 정의할 수 있습니다.\n\n모든 채널이 기본 범위에 포함되지는 않습니다. 반복 가능한 Visual Asset Library를 구성하면 이후 콘텐츠 제작의 일관성을 높일 수 있습니다.",
      en: "Not all information gets the same size. Fast scanners should still understand the core from primary and secondary alone.\n\nVisual Content is not a full brand identity rebuild. Existing identity is applied consistently; if none exists, a minimal visual direction can be defined.\n\nNot every channel is in base scope. A reusable visual asset library can improve consistency for later content.",
