    checksTitle: pickLang(raw.checksTitle, pageLang) || "",
    checksLead: pickLang(raw.checksLead, pageLang) || "",
    checksNote: pickLang(raw.checksNote, pageLang) || "",
    checks: pickLang(raw.checks, pageLang) || [],
    versusLabel: pickLang(raw.versusLabel, pageLang) || "LOGO vs IDENTITY",
    versusTitle: pickLang(raw.versusTitle, pageLang) || "",
    versusLead: pickLang(raw.versusLead, pageLang) || "",
    versusNote: pickLang(raw.versusNote, pageLang) || "",
    versus: pickLang(raw.versus, pageLang) || [],
    conceptFlowLabel: pickLang(raw.conceptFlowLabel, pageLang) || "CONCEPT → SYSTEM",
